\begin{theorem} \label{TheoremLinearRateUniformly} Assume that for a
	fixed $\nu \in [0, 1]$ we have $0 < \Hfnu < +\infty$ and
	$\sigmafnu > 0$. Let parameter $H_0$ in Algorithm 1 be
	small enough:
	\begin{equation} \label{HolderChoosingH}
	\ba{rcl}
	H_0 & \; \leq \; & \frac{ \kappa_f(\nu) }{ \left( F(x_0) - F^{*}
		\right)^{(1 - \nu) / (2 + \nu)  } },
	\ea
	\end{equation}
	where $\kappa_f(\nu)$ is defined
	by~\eqref{KappaDefinition}. Let the sequence $\{ x_k \}_{k
		= 0}^K$ generated by the method satisfy condition:
	\begin{equation} \label{HolderConditionFuncEps}
	F(T_{H_k2^{j}}(x_k)) - F^{*} \; \geq \; \varepsilon \; > \; 0, \qquad
	\quad 0 \leq j \leq i_k, \quad 0 \leq k \leq K - 1.
	\end{equation}
	Then, for every $0 \leq k \leq K - 1$, we have:
	\beq \label{HolderMainResult}
	\ba{cl}
	& F(x_{k + 1}) - F^{*}  \leq \\[5pt]
	& \bigl( 1 - \min\bigl\{  \frac{ (2 + \nu)\left( (1 + \nu) (2
		+ \nu) \right)^{ 1 / (1 + \nu) }  
	    \left( \gammafnu  \right)^{\frac{1}{1 +
	    		\nu}}   }{ (1 + \nu)6^{3/2} \cdot 2^{1/2} \cdot (8
		+ \nu)^{ (1 - \nu) / (2 + 2 \nu) } } , \frac{1}{2} \bigr\}  \bigr) \cdot 
	  \left( F(x_{k}) - F^{*} \right).
	\ea
	\eeq
	Therefore, the rate of convergence is linear, and
	\begin{displaymath}
	\ba{rcl}
	K & \; \leq \; & \max\bigl\{  \left( \gammafnu \right)^{\frac{-1}{1
			+ \nu}} \cdot \frac{1 + \nu}{2 + \nu}  \cdot \frac{6^{3/2} \cdot
		2^{1/2} \cdot (8 + \nu)^{(1 - \nu) / (2 + 2\nu)} }{ \left( (1 +
		\nu)(2 + \nu) \right)^{1 / (1 + \nu)}  } , \; 1 \bigr\} \cdot \log
	\frac{ F(x_0) - F^{*} }{\varepsilon}.
	\ea
	\end{displaymath}
	Moreover, we have the following bound for the total number of oracle
	calls $N_K$ during the first $K$ iterations:
	\begin{equation} \label{HolderOracleCallsBound}
	\ba{rcl}
	N_K & \; \leq \; & 2K  +  \log_2
	\frac{\kappa_f(\nu)}{\varepsilon^{(1 - \nu) / (2 + \nu)}} -
	\log_2 H_0.
	\ea
	\end{equation}
\end{theorem}

