\begin{lemma} \label{UniformlyConvexConsequence}
	Let $f$ be uniformly convex of degree $p \geq 2$ with
	constant $\sigma > 0$ on set $\dom F$. Then, for every $x
	\in \dom F$ and for all $F'(x) \in \partial F(x)$ we have
	\begin{equation} \label{UniformlyConvexGradientBound}
	\ba{rcl}
	F(x) - F^{*} & \; \leq \; & \frac{p - 1}{p} \left( \frac{1}{\sigma}
	\right)^{\frac{1}{p - 1}} \|F'(x)\|_{*}^{\frac{p}{p - 1}}.
	\ea
	\end{equation}
\end{lemma}

\begin{proof}
	\noindent
	In view of~\eqref{UniformlyConvexLowerBound}, 
	bound \eqref{UniformlyConvexGradientBound}
	follows as in the proof of Lemma~3 
	in~\cite{nesterov2008accelerating}.
\qed
\end{proof}

\begin{proof}
	Denote $\kappa(x) \equiv \sum_{i = 1}^m e^{\langle a_i, x \rangle}$.
	Let us fix arbitrary $x, y \in \E$ and direction $h \in \E$. Then,
	straightforward computation gives:
	$$
	\ba{rcl}
	\langle \nabla f(x), h \rangle &\; = \;& \frac{1}{\kappa(x)}
	\sum_{i = 1}^m e^{\langle a_i, x \rangle} \langle a_i, h \rangle, \\[6pt]
	\langle \nabla^2 f(x)h, h \rangle &\; =\;&
	 \frac{1}{\kappa(x)} \sum_{i = 1}^m e^{\langle a_i, x \rangle}
	\langle
	a_i, h \rangle^2 - \bigl( \frac{1}{\kappa(x)} \sum_{i = 1}^m
	e^{\langle a_i, x \rangle} \langle a_i, h \rangle  \bigr)^2 \\[5pt]
	&\; = \;& \frac{1}{\kappa(x)} \sum_{i = 1}^m e^{\langle a_i, x \rangle}
	\left( \langle
	a_i, h \rangle - \langle \nabla f(x), h \rangle
	\right)^2 \; \geq \; 0.
	\ea
	$$
	Hence, we get
	$$
	\ba{rcl}
	\| \nabla^2 f(x) \| & = & \max\limits_{\|h\| \leq 1} \langle \nabla^2 f(x)
	h, h \rangle \;
	\leq \;  \max\limits_{\|h\| \leq 1} \sum_{i = 1}^m \langle a_i, h \rangle^2
	\;
	= \; \max\limits_{\|h\| \leq 1} \|h\|^2 \; = \; 1.
	\ea
	$$
	Since all Hessians of function $f$ are positive definite,
	we conclude that $\Hf(0) \leq 1$. Inequality $\Hf(1) \leq
	2$ can be easily obtained from the following
	representation of the third derivative:
	$$
	\ba{rcl}
	f'''(x)[h,h,h]  & \; = \; & {1 \over \kappa(x)}
	\sum\limits_{i=1}^m e^{\la a_i, x \ra} \left( \la a_i, h
	\ra - \la \nabla f(x), h \ra \right)^3\\
	\\
	& \;  \leq \; & \la \nabla^2 f(x) h, h \ra \max\limits_{1 \leq
		i,j \leq m } \la a_i - a_j , h \ra \; \leq \; 2 \| h \|^3.
	\ea
	$$
\qed
\end{proof}

\begin{lemma} \label{LemmaStepHolder}
	Let $0 < \Hfnu < +\infty$ and $\sigmafnu > 0$ for some
	$\nu \in [0,1]$. Then, for arbitrary $x \in \dom F$ and $H
	> 0$ we have:
	\beq \label{OneStepProgressHolder}
	\ba{cl}
	& F(x) - M_H^{*}(x)  \\[5pt] 
	& \quad \geq \; \min\Bigl[ \left( F(x) -
	F^{*} \right) \cdot \frac{(1 + \nu)}{(2 + \nu)} \cdot
	\min\bigl\{\bigl( \frac{(1 + \nu) \gammafnu}{2(2 + \nu)}  \bigr)^{\frac{1}{1 + \nu}}, 
	\; 1\bigr\} ,   \\[5pt]
	& \; \qquad \qquad \left( F(T_H(x)) - F^{*} \right)^{\frac{3(1 + \nu)}{2(2 + \nu)}}
	\cdot \bigl ( \frac{2 + \nu}{1 + \nu}  \bigr)^{\frac{3(1 + \nu)}{2(2
			+ \nu)}} \cdot \frac{(\sigmafnu)^{\frac{3}{2(2 + \nu)}}}{ 3 \sqrt{H}
	}  \;  \Bigr]. 
	\ea
	\eeq
\end{lemma}

\begin{proof}
	Let us consider two cases. 1) 
	$H r_H^{1 - \nu}(x) \leq \frac{2 \Hfnu}{1 + \nu}$.
		Then, for arbitrary $y \in \dom F$, we have:
		$$
		\ba{rcl}
		M_H^{*}(x) 
		& := &  Q(x; T_H(x)) +
		\frac{H}{6}\|T_H(x) - x\|^3 + h(T_H(x)) \\[7pt]
		& \leq &  Q(x; y) + \frac{H r_H^{1 - \nu}(x) \|y -
			x\|^{2 + \nu}}{2 (2 + \nu) } + h(y) \\[5pt]
		& \overset{\eqref{HolderHessianFuncBound}}{\leq} &  
		F(y) +
		\frac{\Hfnu \|y - x\|^{2 + \nu}}{(1 + \nu)(2 + \nu)} +
		\frac{H r_H^{1 - \nu}(x) \|y - x\|^{2 + \nu}}{2 (2 + \nu) }
		\\[7pt]
		& \leq &
		 F(y) +  \frac{2\Hfnu \|y - x\|^{2 +
		\nu}}{(1 + \nu)(2 + \nu)},
		\ea
		$$
		where the first inequality follows from the fact, that
		$$
		\ba{rcl}
		T_H(x) & = & \argmin\limits_{y \in \dom F} \bigl\{ Q(x; y)
		+ \frac{H r_H^{1 - \nu}(x) \|y -
			x\|^{2 + \nu}}{2 (2 + \nu) } + h(y) \bigr\}.
		\ea
		$$
		Let us restrict $y$ to the segment: $y = \alpha x^{*} + (1 -
		\alpha) x,$ with $\alpha \in [0, 1]$. Taking into account the
		uniform convexity, we get:
		$$
		\ba{rcl}
		M_H^{*}(x) & \leq &  F(x) - \alpha \left( F(x) -
		F^{*} \right) + \alpha^{2 + \nu} \frac{2\Hfnu \|x^{*} - x\|^{2 +
				\nu}} {(1 + \nu)(2 + \nu)} \quad \\[5pt]
		& \overset{\eqref{UniformlyConvexLowerBound}}{\leq} &  
		F(x)
		-  \Bigl(\alpha  - \alpha^{2 + \nu} \frac{2\Hfnu}{  (1 + \nu)
			\sigmafnu}
		\Bigr) \left( F(x) - F^{*} \right).
		\ea
		$$
		The minimum of the right-hand side is attained at
		$
		\alpha^{*} = \min\bigl\{\frac{(1 + \nu)\gammafnu}{2(2 + \nu)}, 1 \bigr\}^{\frac{1}{1 + \nu}}.
		$
		Plugging this value into the bound, we have:
		\begin{displaymath}
		\ba{rcl}
		M^{*}_H(x) & \leq & F(x)  -   \min\bigl\{ \bigl(
		\frac{(1 + \nu)\gammafnu}{2(2 + \nu)}   \bigr)^{1 / (1 + \nu)}
		, \; 1 \bigr\} \cdot \frac{(1 + \nu)}{(2 + \nu)} \cdot \left(
		F(x) - F^{*} \right),
		\ea
		\end{displaymath}
		and this is the first argument of the minimum in
		\eqref{OneStepProgressHolder}.

		2) $H r_H^{1 - \nu}(x) > \frac{2 \Hfnu}{1 + \nu}.$
		By~\eqref{CubicGradNewPoint}, we have the bound:
		\begin{equation} \label{NextPointGradBound2}
		\ba{rcl}
		\| F'(T_H(x)) \|_{*} & \; < \; & Hr_H^2(x).
		\ea
		\end{equation}
		Using the fact that $\nabla^2 f(x) \succeq 0$, we get the second argument of the
		minimum:
	$$
	\ba{rcl}
	F(x) - M_H^{*}(x)
	& \overset{\eqref{CubicModelMinimumExpression}}{\geq} &
	\frac{Hr^3_H(x)}{3} \quad  \overset{ \eqref{NextPointGradBound2}
	}{\geq} \quad \frac{\| F'(T_H(x)) \|_{*}^{\frac32}}{3 \sqrt{H}}
	\\[5pt]
	& \overset{\eqref{UniformlyConvexGradientBound}}{\geq} &
	 \left(
	\frac{2 + \nu}{1 + \nu}  \right)^{\frac{3(1 + \nu)}{2(2 + \nu)}}
	\cdot \frac{(\sigmafnu)^{\frac{3}{2(2 + \nu)}}}{ 3 \sqrt{H} } \cdot
	\left( F(T_H(x)) - F^{*} \right)^{\frac{3(1 + \nu)}{2(2 + \nu)}}.
	\ea
	$$
\qed
\end{proof}

\begin{lemma} \label{LemmaUpHolder} Assume that for a fixed
	$x \in \dom F$ the parameter $H > 0$ is such that:
	\begin{equation} \label{LemmaUpHolderCondition}
	\ba{rcl}
	F(T_H(x)) & \; > \; & M^{*}_H(x).
	\ea
	\end{equation}
	If for some $\nu \in [0, 1]$, we have $\sigmafnu > 0$, then it holds:
	\begin{equation} \label{LemmaUpHolder3}
	\ba{rcl}
	H \left( F(T_{2H}(x)) - F^{*} \right)^{\frac{1 - \nu}{2 + \nu}}
	& \; < \; & \kappa_f(\nu).
	\ea
	\end{equation}
\end{lemma}

\begin{proof}
	Firstly, let us prove that from~\eqref{LemmaUpHolderCondition} we
	have:
	\begin{equation} \label{LemmaUpHolderBound1}
	\ba{rcl}
	H r^{1 - \nu}_H(x) & \; < \; & \frac{6 \Hfnu}{(1 + \nu)(2 + \nu)}.
	\ea
	\end{equation}
	Assuming by contradiction, $H r^{1 - \nu}_H(x) \; \geq \; \frac{6
		\Hfnu}{(1 + \nu)(2 + \nu)}$, we get:
	$$
	\ba{rcl}
	M_H^{*}(x)  & := & \frac{H \|T_H(x) - x\|^3}{6} + Q(x;
	T_H(x)) + h(T_H(x)) \\[5pt]
	& \geq & \frac{\Hfnu \|T_H(x) - x\|^{2 + \nu}}{(1 + \nu)(2 +
		\nu)} + Q(x; T_H(x)) + h(T_H(x)) \\[5pt]
	& \overset{\eqref{HolderHessianFuncBound}}{\geq} & F(T_H(x)),
	\ea
	$$
	which contradicts~\eqref{LemmaUpHolderCondition}.
	Secondly, by its definition, $M^*_H(x)$ is a concave function of $H$.
	Therefore, its derivative
	$
	{d \over d H} M^*_H(x)  =  {1 \over 6} r_H^3(x)
	$
	is non-increasing. Hence, it holds:
	\beq \label{LemmaUpHolderBound2}
	\ba{rcl}
	r_{2H}(x) & \leq & r_H(x)
	\overset{\eqref{LemmaUpHolderBound1}}{<} 
	\bigl( \frac{6 \Hfnu}{(1 + \nu)(2 + \nu) H} \bigr)^{\frac{1}{1 - \nu}}.
	\ea
	\eeq
	Finally, by the smoothness and the uniform convexity, we obtain:
	$$
	\ba{cl}
	& H \left( F(T_{2H}(x)) - F^{*} \right)^{\frac{1 - \nu}{2 + \nu}}
	\;\; \refLE{UniformlyConvexGradientBound} \;\;
	H \left(
	\frac{1 + \nu}{2 + \nu} \bigl( \frac{1}{\sigmafnu}
	\bigr)^{\frac{1}{1 + \nu}}  \right)^{\frac{1 - \nu}{2 + \nu}} 
	\| F'(T_{2H}(x)) \|_{*}^{\frac{1 - \nu}{1 + \nu}}  \\[5pt]
	& \quad \refLE{CubicGradNewPoint} 
	H \left(
	\frac{1 + \nu}{2 + \nu} \bigl( \frac{1}{\sigmafnu}
	\bigr)^{\frac{1}{1 + \nu}}  \right)^{\frac{1 - \nu}{2 + \nu}} 
	\Bigl(
	r^{1 +\nu}_{2H}(x) \cdot \left(  \frac{\Hfnu}{1 + \nu} + H r^{1 -
		\nu}_{2H}(x) \right)
	\Bigr)^{\frac{1 - \nu}{1 + \nu}} \\[5pt]
	& \quad \overset{\eqref{LemmaUpHolderBound2}}{<} 
	H \left(
	\frac{1 + \nu}{2 + \nu} \bigl( \frac{1}{\sigmafnu}
	\bigr)^{\frac{1}{1 + \nu}}  \right)^{\frac{1 - \nu}{2 + \nu}} 
	\Bigl( 
	r^{1+\nu}_{2H}(x) \cdot \frac{(8 + \nu) \Hfnu}{(1 + \nu)(2 + \nu)}
	\Bigr)^{\frac{1 - \nu}{1 + \nu}} \\[5pt]
	& \quad \overset{\eqref{LemmaUpHolderBound2}}{<} 
		\left(
	\frac{1 + \nu}{2 + \nu} \bigl( \frac{1}{\sigmafnu}
	\bigr)^{\frac{1}{1 + \nu}}  \right)^{\frac{1 - \nu}{2 + \nu}} 
	\left( \frac{\Hfnu}{(1 + \nu)(2 + \nu)}  \right)^{\frac{2}{1 + \nu}}
	6  (8 + \nu)^{\frac{1 - \nu}{1 + \nu}}
	\; =: \; \kappa_f(\nu).
	\ea
	$$
\qed
\end{proof}

\begin{proof}
	The proof is based on Lemmas~\ref{LemmaStepHolder}
	and~\ref{LemmaUpHolder}, and monotonicity of the sequence
	$\bigl\{ F(x_k)  \bigr\}_{k \geq 0}$.
		Firstly, we need to show that every iteration of the method is
	well-defined. Namely, we are going to verify that for a fixed $0 \leq
	k \leq K-1$, there exists a finite integer $\ell \geq 0$ such that
	either $F(T_{H_k 2^{\ell}}(x_k) ) \leq M_{H_k 2^{\ell}}^{*}(x_k)$ or
	$F(T_{H_k 2^{\ell + 1}}(x_k)) - F^{*} < \varepsilon$.
		Indeed, let us set
	\begin{equation} \label{Th2HLowerBound}
	\ba{rcl}
	\ell := \max\left\{0,  \log_2 \left \lceil
	\frac{\kappa_f(\nu)}{H_k \varepsilon^{(1 - \nu) / (2 + \nu)} }
	\right\rceil  \right\}, 
	& \quad \text{and} \quad &
	H := H_k
	2^{\ell}  \geq  \frac{\kappa_f(\nu)}{\varepsilon^{(1 - \nu) / (2
			+ \nu)}}.
	\ea
	\end{equation}
	Then, if we have both $F(T_{H}(x_k)) > M_{H}^{*}(x_k)$ and
	$F(T_{2H}(x_k)) - F^{*}
	\geq \varepsilon$, we get by Lemma \ref{LemmaUpHolder}:
	\begin{displaymath}
	\ba{rcl}
	H & \; \overset{\eqref{LemmaUpHolder3}}{<} \; &
	\frac{\kappa_f(\nu)}{\left( F(T_{2H}(x_k)) - F^{*}  \right)^{(1 - \nu)
			/ (2 + \nu)}  } \; \leq \; \frac{\kappa_f(\nu)}{\varepsilon^{(1
			- \nu) / (2 + \nu)}},
	\ea
	\end{displaymath}
	which contradicts~\eqref{Th2HLowerBound}. Therefore, if we are unable
	to find the value $0 \leq i_k \leq \ell$ (see line~1 of
	Algorithm) in a finite number of steps, that only means we have
	already solved the problem up to accuracy $\varepsilon$.



	Now, let us show that for every $0 \leq k \leq K$ it holds:
	\begin{equation} \label{Th2UsefulBound}
	\ba{rcl}
	H_k \left( F(x_k) - F^{*} \right)^{\frac{1 - \nu}{2 + \nu}} 
	& \leq &
	\max \left\{ \kappa_f(\nu), \; H_0 \left( F(x_0) - F^{*}
	\right)^{\frac{1 - \nu}{2 + \nu}} \right\}.
	\ea
	\end{equation}
	This inequality is obviously valid for $k = 0$. Assume it
	is also valid for some $k \geq 0$. Then, by definition of
	$H_{k + 1}$ (see line~3 of Algorithm), we have $H_{k +
		1} = H_k 2^{i_k - 1}$. 
	There are two cases.
		1) $i_k = 0$. Then, $H_{k + 1} < H_k$. By monotonicity of
		$\bigl\{ F(x_k) \bigr\}_{k \geq 0}$ and by induction, we get:
		$$
		\ba{rcl}
		H_{k + 1} \left( F(x_{k + 1}) - F^{*} \right)^{\frac{1 - \nu}{2 +
				\nu}}  & \; < \; & H_k \left( F(x_k) - F^{*} \right)^{\frac{1 -
				\nu}{2 + \nu}} \\[5pt]
		& \; \leq \; & 
		\max \left\{ \kappa_f(\nu), \; H_0 \left( F(x_0) -
		F^{*} \right)^{\frac{1 - \nu}{2 + \nu}} \right\}.
		\ea
		$$

		2) $i_k > 0$. Then, applying Lemma~\ref{LemmaUpHolder} with $H
		:= H_k 2^{i_k - 1} = H_{k + 1}$ and $x :=
		x_{k}$, we have:
		\begin{displaymath}
		\ba{rcl}
		H_{k + 1} \left( F(x_{k + 1}) - F^{*} \right)^{\frac{1 - \nu}{2 +
				\nu}} & \; = \; & H \left( F(T_{2H}(x)) - F^{*}
		\right)^{\frac{1 - \nu}{2 + \nu}} \;
		\overset{\eqref{LemmaUpHolder3}}{\leq} \; \kappa_f(\nu).
		\ea
		\end{displaymath}
	Thus, \eqref{Th2UsefulBound} is true by induction.
	Choosing $H_0$ small enough~\eqref{HolderChoosingH}, we have:
	\begin{equation} \label{HolderHtGoodBound}
	\ba{rcl}
	2H_{k} \left( F(x_k) - F^{*}\right)^{\frac{1 - \nu}{2 + \nu}} 
	& \; \leq \; & 
	2\kappa_f(\nu), \qquad 0 \leq k \leq K.
	\ea
	\end{equation}
	From Lemma~\ref{LemmaStepHolder} we know, that one of the two
	following estimates is true (denote $\delta_k := F(x_k) - F^{*}$):


	\begin{enumerate}
		\item[1)] $F(x_k) - F(x_{k + 1})  \geq \alpha \cdot \delta_k
		 \;  \Leftrightarrow  \;  \delta_{k + 1}  \leq (1 -
		\alpha) \cdot \delta_k, \; $ \textit{or}

		\item[2)] $F(x_k) - F(x_{k + 1})  \geq \beta \cdot \delta_{k +
			1}  \; \Leftrightarrow \;  \delta_{k + 1}
	 	\leq (1 + \beta)^{-1} \delta_k  \leq  (1 - \min\{\beta,
		1\} / 2) \cdot \delta_k$,
	\end{enumerate}
	where
	$
	\alpha  
	 := 
	 \frac{1 + \nu}{2 + \nu} \cdot
	\min\bigl\{\bigl(  \frac{(1 + \nu) \gammafnu}{2(2 + \nu)} \bigr)^{
		\frac{1}{1 + \nu}}, \; 1\bigr\},
	$
	and
	$$
	\ba{rcl}
	\beta 
	 & := & 
	\bigl( \frac{2 + \nu}{1 + \nu}
	\bigr)^{\frac{3(1 + \nu)}{2(2 + \nu)}} \cdot
	\frac{(\sigmafnu)^{\frac{3}{2(2 + \nu)}}}{3 (2 \kappa_f(\nu))^{1/2}
	}
	\; \refEQ{KappaDefinition} \;
	\frac{2 + \nu}{1 + \nu} \cdot \frac{ 2^{1/2} \cdot
		\left( (1 + \nu) (2 + \nu)  \right)^{\frac{1}{1 + \nu}} }{6^{3/2}
		\cdot (8 + \nu)^{(1 - \nu) / (2 + 2\nu)}} \cdot \gammafnu^{\frac{1}{1
			+ \nu}}.
	\ea
	$$
	It remains to notice, that $\alpha \geq \min \bigl\{\beta, 1\bigr\} /
	2$. Thus, we obtain~\eqref{HolderMainResult}.

	Finally, let us estimate the total number of the oracle calls $N_K$
	during the first $K$ iterations. At each
	iteration, the oracle is called $i_k + 1$ times, and we have $H_{k +
		1} = H_k 2^{i_k - 1}$. Therefore,
	$$
	\ba{rcl}
	N_K & \; = \; & \sum_{k = 0}^{K - 1} (i_k + 1) \; = \; \sum_{k = 0}^{K -
		1} \left( \log_2 \frac{H_{k + 1}}{H_k} + 2\right) \\[5pt]
	& \; = \; & 2K + \log_2
	H_{K} - \log_2 H_0
	\; \overset{\eqref{HolderHtGoodBound},
		\eqref{HolderConditionFuncEps}}{\leq} \;
	2K + \log_2
	\frac{\kappa_f(\nu)}{\varepsilon^{(1 - \nu) / (2 + \nu)}} - \log_2
	H_0.
	\ea
	$$
\qed
\end{proof}

