\begin{lemma} \label{UniformlyConvexConsequence}
	Let $f$ be uniformly convex of degree $p \geq 2$ with
	constant $\sigma > 0$ on set $\dom F$. Then, for every $x
	\in \dom F$ and for all $F'(x) \in \partial F(x)$ we have
	\begin{equation} \label{UniformlyConvexGradientBound}
	\ba{rcl}
	F(x) - F^{*} & \; \leq \; & \frac{p - 1}{p} \left( \frac{1}{\sigma}
	\right)^{\frac{1}{p - 1}} \|F'(x)\|_{*}^{\frac{p}{p - 1}}.
	\ea
	\end{equation}
\end{lemma}

\begin{proof}
	\noindent
	In view of~\eqref{UniformlyConvexLowerBound}, 
	bound \eqref{UniformlyConvexGradientBound}
	follows as in the proof of Lemma~3 
	in~\cite{nesterov2008accelerating}.
\qed
\end{proof}

\begin{lemma} \label{LemmaStepHolder}
	Let $0 < \Hfnu < +\infty$ and $\sigmafnu > 0$ for some
	$\nu \in [0,1]$. Then, for arbitrary $x \in \dom F$ and $H
	> 0$ we have:
	\beq \label{OneStepProgressHolder}
	\ba{cl}
	& F(x) - M_H^{*}(x)  \\[5pt] 
	& \quad \geq \; \min\Bigl[ \left( F(x) -
	F^{*} \right) \cdot \frac{(1 + \nu)}{(2 + \nu)} \cdot
	\min\bigl\{\bigl( \frac{(1 + \nu) \gammafnu}{2(2 + \nu)}  \bigr)^{\frac{1}{1 + \nu}}, 
	\; 1\bigr\} ,   \\[5pt]
	& \; \qquad \qquad \left( F(T_H(x)) - F^{*} \right)^{\frac{3(1 + \nu)}{2(2 + \nu)}}
	\cdot \bigl ( \frac{2 + \nu}{1 + \nu}  \bigr)^{\frac{3(1 + \nu)}{2(2
			+ \nu)}} \cdot \frac{(\sigmafnu)^{\frac{3}{2(2 + \nu)}}}{ 3 \sqrt{H}
	}  \;  \Bigr]. 
	\ea
	\eeq
\end{lemma}

\begin{lemma} \label{LemmaUpHolder} Assume that for a fixed
	$x \in \dom F$ the parameter $H > 0$ is such that:
	\begin{equation} \label{LemmaUpHolderCondition}
	\ba{rcl}
	F(T_H(x)) & \; > \; & M^{*}_H(x).
	\ea
	\end{equation}
	If for some $\nu \in [0, 1]$, we have $\sigmafnu > 0$, then it holds:
	\begin{equation} \label{LemmaUpHolder3}
	\ba{rcl}
	H \left( F(T_{2H}(x)) - F^{*} \right)^{\frac{1 - \nu}{2 + \nu}}
	& \; < \; & \kappa_f(\nu).
	\ea
	\end{equation}
\end{lemma}

\begin{proof}
	Firstly, let us prove that from~\eqref{LemmaUpHolderCondition} we
	have:
	\begin{equation} \label{LemmaUpHolderBound1}
	\ba{rcl}
	H r^{1 - \nu}_H(x) & \; < \; & \frac{6 \Hfnu}{(1 + \nu)(2 + \nu)}.
	\ea
	\end{equation}
	Assuming by contradiction, $H r^{1 - \nu}_H(x) \; \geq \; \frac{6
		\Hfnu}{(1 + \nu)(2 + \nu)}$, we get:
	$$
	\ba{rcl}
	M_H^{*}(x)  & := & \frac{H \|T_H(x) - x\|^3}{6} + Q(x;
	T_H(x)) + h(T_H(x)) \\[5pt]
	& \geq & \frac{\Hfnu \|T_H(x) - x\|^{2 + \nu}}{(1 + \nu)(2 +
		\nu)} + Q(x; T_H(x)) + h(T_H(x)) \\[5pt]
	& \overset{\eqref{HolderHessianFuncBound}}{\geq} & F(T_H(x)),
	\ea
	$$
	which contradicts~\eqref{LemmaUpHolderCondition}.
	Secondly, by its definition, $M^*_H(x)$ is a concave function of $H$.
	Therefore, its derivative
	$
	{d \over d H} M^*_H(x)  =  {1 \over 6} r_H^3(x)
	$
	is non-increasing. Hence, it holds:
	\beq \label{LemmaUpHolderBound2}
	\ba{rcl}
	r_{2H}(x) & \leq & r_H(x)
	\overset{\eqref{LemmaUpHolderBound1}}{<} 
	\bigl( \frac{6 \Hfnu}{(1 + \nu)(2 + \nu) H} \bigr)^{\frac{1}{1 - \nu}}.
	\ea
	\eeq
	Finally, by the smoothness and the uniform convexity, we obtain:
	$$
	\ba{cl}
	& H \left( F(T_{2H}(x)) - F^{*} \right)^{\frac{1 - \nu}{2 + \nu}}
	\;\; \refLE{UniformlyConvexGradientBound} \;\;
	H \left(
	\frac{1 + \nu}{2 + \nu} \bigl( \frac{1}{\sigmafnu}
	\bigr)^{\frac{1}{1 + \nu}}  \right)^{\frac{1 - \nu}{2 + \nu}} 
	\| F'(T_{2H}(x)) \|_{*}^{\frac{1 - \nu}{1 + \nu}}  \\[5pt]
	& \quad \refLE{CubicGradNewPoint} 
	H \left(
	\frac{1 + \nu}{2 + \nu} \bigl( \frac{1}{\sigmafnu}
	\bigr)^{\frac{1}{1 + \nu}}  \right)^{\frac{1 - \nu}{2 + \nu}} 
	\Bigl(
	r^{1 +\nu}_{2H}(x) \cdot \left(  \frac{\Hfnu}{1 + \nu} + H r^{1 -
		\nu}_{2H}(x) \right)
	\Bigr)^{\frac{1 - \nu}{1 + \nu}} \\[5pt]
	& \quad \overset{\eqref{LemmaUpHolderBound2}}{<} 
	H \left(
	\frac{1 + \nu}{2 + \nu} \bigl( \frac{1}{\sigmafnu}
	\bigr)^{\frac{1}{1 + \nu}}  \right)^{\frac{1 - \nu}{2 + \nu}} 
	\Bigl( 
	r^{1+\nu}_{2H}(x) \cdot \frac{(8 + \nu) \Hfnu}{(1 + \nu)(2 + \nu)}
	\Bigr)^{\frac{1 - \nu}{1 + \nu}} \\[5pt]
	& \quad \overset{\eqref{LemmaUpHolderBound2}}{<} 
		\left(
	\frac{1 + \nu}{2 + \nu} \bigl( \frac{1}{\sigmafnu}
	\bigr)^{\frac{1}{1 + \nu}}  \right)^{\frac{1 - \nu}{2 + \nu}} 
	\left( \frac{\Hfnu}{(1 + \nu)(2 + \nu)}  \right)^{\frac{2}{1 + \nu}}
	6  (8 + \nu)^{\frac{1 - \nu}{1 + \nu}}
	\; =: \; \kappa_f(\nu).
	\ea
	$$
\qed
\end{proof}

